#!/bin/bash
set -euo pipefail
test "$(id -un)" = pwa209
case "$(hostname -f)" in *.narval.calcul.quebec) ;; *) exit 2 ;; esac
module load StdEnv/2023 python/3.11.5 cuda/12.6 arrow/19.0.1
source /home/pwa209/hhw-environment/bin/activate
export PYTHONPATH=/scratch/pwa209/horsehair-worm/releases/20261021-6ed201653dfa-4f3903d7c26e/src
export PYTHONDONTWRITEBYTECODE=1 TZ=UTC
python -B -u - <<'PY'
from pathlib import Path,PurePosixPath
import base64,hashlib,importlib.util,json,os,shlex,subprocess,zlib
from horsehair import slurm
from horsehair.core import read_json,source_identity,canonical_hash,exclusive_file_lock,atomic_json
assert os.geteuid()==3164768
r=Path('/scratch/pwa209/horsehair-worm');s=r/'maintenance/study-census-resilience-consumers-v5-20261103'
payload={'run-census-resilience-consumer-v2-20261024.py': {'sha256': 'b457d18789bf9ba34b023d76953078fdd7dfb7962987a48145b7214a79ef6d59', 'bytes': 40380, 'data': ''}, 'test_census_resilience_consumers_v2_20261024.py': {'sha256': 'ab5ef0198a7d4289df5147892ceda68dbe39d7617d38a4ce1201af2766a10867', 'bytes': 46855, 'data': ''}, 'qualify-census-resilience-consumers-v2-20261024.py': {'sha256': '16af763f0a3c717a16b8c79e2f0a8107d70bb1a815a4442708eead1488d8f7e6', 'bytes': 8288, 'data': ''}, 'build-consumer-plan.py': {'sha256': '696ef4033d4fce92c73e32ae33ae98c0cfedb34d59f494e18a4feeaa1cd2e8e3', 'bytes': 10187, 'data': ''}, 'source-manifest.json': {'sha256': '4b043a5906385a05fd2c0ea4525a8a6b978f70dbae344b4e2a603a6d5f8315ab', 'bytes': 859, 'data': ''}}
s.mkdir(mode=0o700,parents=True,exist_ok=True)
assert s==s.resolve() and not s.is_symlink() and s.stat().st_uid==3164768
for name,item in payload.items():
 raw=zlib.decompress(base64.b64decode(item['data']));assert len(raw)==item['bytes'] and hashlib.sha256(raw).hexdigest()==item['sha256']
 p=s/name
 if p.exists():assert not p.is_symlink() and p.read_bytes()==raw
 else:
  with p.open('xb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
  p.chmod(0o444)
manifest_sha='4b043a5906385a05fd2c0ea4525a8a6b978f70dbae344b4e2a603a6d5f8315ab'
spec=importlib.util.spec_from_file_location('consumer_v5_native',s/'run-census-resilience-consumer-v2-20261024.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
mb={'path':str(s/'source-manifest.json'),'sha256':manifest_sha};manifest,pins=m.source_manifest(mb)
framework=r/'releases/20261021-6ed201653dfa-4f3903d7c26e';config=read_json(framework/'configs/study.json')
assert source_identity(framework)['sha256']==m.SOURCE and canonical_hash(config)==m.CONFIG
phase='study-census-resilience-consumers-qualification-v5-20261103';directory=r/'plans'/phase;ledger=r/'state'/(phase+'-submission.json')
area=s/'qualification-registration';area.mkdir(mode=0o700,exist_ok=False)
assert not directory.exists() and not ledger.exists()
directory.mkdir();name='census-resilience-consumer-qualification-v5';script=directory/(name+'.sbatch');helper=s/m.QUALIFIER_NAME
flags=['--native-plan',str(directory/'plan.json'),'--native-ledger',str(ledger),'--native-task',name,'--native-script',str(script),'--source-manifest',mb['path'],'--source-manifest-sha256',mb['sha256']]
command=shlex.join(['python','-s','-B',str(helper),*flags])
text=slurm._script(config,framework,name,command,cpus=4,memory='16G',hours=1,gpu=False).replace('set -euo pipefail','#SBATCH --hold\nset -euo pipefail',1)
script.write_text(text)
task={'name':name,'script':str(script),'script_sha256':canonical_hash(text),'depends':[],'external_dependencies':[],'dependency_kind':'afterok','resources':{'cpus':4,'memory':'16G','hours':1,'gpu':False,'array':None},'command':command,'census_resilience_consumer_qualification':{'helper':m.locator(helper),'source_manifest':mb,'suite':manifest['suites']['consumers']}}
plan={'schema_version':1,'root':str(r),'phase':phase,'release_identity':source_identity(framework),'config_sha256':canonical_hash(config),'tasks':[task]}
atomic_json(directory/'plan.json',plan);counter=[0]
def runner(cmd,**kwargs):
 counter[0]+=1;prefix=area/str(counter[0]);atomic_json(Path(str(prefix)+'-intent.json'),{'command':cmd,'automatic_replay_permitted':False})
 result=subprocess.run(cmd,**kwargs,timeout=90);atomic_json(Path(str(prefix)+'-response.json'),{'code':result.returncode,'stdout':result.stdout,'stderr':result.stderr});return result
with exclusive_file_lock(r/'state/af-campaign-registration.mutex',timeout=180):
 record=slurm.submit(directory/'plan.json',ledger,runner=runner);job=record['tasks'][name]['job_id']
 p=subprocess.run(['scontrol','show','job',job,'-o'],text=True,capture_output=True,timeout=90);p.check_returncode();assert not p.stderr
 f=dict(t.split('=',1) for t in shlex.split(p.stdout) if '=' in t)
 assert f['JobId']==job and f['UserId']=='pwa209(3164768)' and f['JobState']=='PENDING' and f['Reason']=='JobHeldUser'
 assert f['Command']==str(script) and f['JobName']=='hhw-'+name and f['Account']=='def-ptewarie_cpu' and f['NumCPUs']=='4' and f['MinMemoryNode'] in {'16G','16384M'} and m.seconds(f['TimeLimit'])==3600
 atomic_json(area/'held-native.json',f)
runner(['scontrol','release',job],text=True,capture_output=True)
p=subprocess.run(['scontrol','show','job',job,'-o'],text=True,capture_output=True,timeout=90);p.check_returncode();assert not p.stderr
f=dict(t.split('=',1) for t in shlex.split(p.stdout) if '=' in t)
assert f['JobId']==job and f['UserId']=='pwa209(3164768)' and f['Command']==str(script)
assert f['JobState'] in {'RUNNING','COMPLETING','COMPLETED'} or f['JobState']=='PENDING' and f['Reason'] not in {'JobHeldUser','JobHeldAdmin'} and int(f['Priority'])>0
receipt={'status':'native_consumer_qualification_registered_and_released','job_id':job,'source_manifest':mb,'tests':manifest['suites']['consumers']['tests'],'actual_unheld_native':f}
atomic_json(area/'registration.json',receipt);print('CONSUMER_V3_QUALIFICATION '+json.dumps(receipt),flush=True)

PY
